    <h2>K?t lu?n</h2>
    <p>Ch?n MacBook Air M2 n?u b?n ?u tiên pin trâu, h? sinh thái Apple. Ch?n Dell XPS 13 n?u c?n Windows, giá t?t h?n và thi?t k? ??p m?t.</p>', TIMESTAMPTZ '2025-01-11T15:20:00Z', 'https://www.gstatic.com/webp/gallery/2.jpg', TIMESTAMPTZ '2025-01-12T10:30:00Z', 'so-sanh-macbook-air-m2-vs-dell-xps-13', 'Published', 'Hai chi?c laptop cao c?p ???c yêu thích nh?t hi?n nay. MacBook Air M2 v?i hi?u n?ng chip ARM xu?t s?c hay Dell XPS 13 v?i thi?t k? tinh t? và Windows 11? Cùng phân tích chi ti?t.', 'So sánh MacBook Air M2 vs Dell XPS 13: Nên ch?n laptop nào?', TIMESTAMPTZ '2025-01-12T10:15:00Z', 890);
    INSERT INTO blog_posts ("Id", "AuthorId", "Content", "CreatedAt", "FeaturedImageUrl", "PublishedAt", "Slug", "Status", "Summary", "Title", "UpdatedAt", "ViewCount")
    VALUES (3, 1, '<h2>Thi?t k? sang tr?ng, S Pen tích h?p</h2>
